// @ts-check
import withNuxt from './.nuxt/eslint.config.mjs'

export default withNuxt({
  // `app/components/ui/` is generated by the shadcn-vue CLI and is replaced
  // wholesale whenever a component is re-added. Holding it to our own style
  // rules would mean re-editing vendored files after every `shadcn-vue add`,
  // so the stylistic rules it trips are switched off for that directory only.
  files: ['app/components/ui/**'],
  rules: {
    'vue/require-default-prop': 'off'
  }
})
